--scheme: dark;
color-scheme: dark;
--bg: #070d0b;
--bg2: #0b1411;
--surface: #101d19;
--surface2: #162822;
--ink: #ecf5f2;
--muted: #b8d0c8;
--faint: #8ea8a0;
--cardmeta: #d5e8e1;
--gold: #8fe0c4;
--gold-soft: #c2f2e0;
--gold-deep: #2f7860;
--on-gold: #05140f;
