extra_css:
/* The Glasshouse surfaces: scoped to html[data-atmo="glasshouse"] only. */
html[data-atmo="glasshouse"] .card, html[data-atmo="glasshouse"] .panel, html[data-atmo="glasshouse"] .gx-card {
  background: radial-gradient(125% 80% at 50% 0%, rgba(143, 224, 196,.08), transparent 62%), linear-gradient(180deg, #162822e0, #070d0bf2);
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  box-shadow: inset 0 1px 0 rgba(143, 224, 196,.30), inset 0 0 0 1px rgba(143, 224, 196,.22), 0 18px 46px rgba(0,0,0,.78);
  transition: box-shadow .4s ease, transform .5s cubic-bezier(.2,1,.3,1), background .6s ease; }
html[data-atmo="glasshouse"] .card:hover, html[data-atmo="glasshouse"] .gx-card:hover {
  transform: translateY(-2px);
  box-shadow: inset 0 1px 0 rgba(143, 224, 196,.52), inset 0 0 0 1px rgba(143, 224, 196,.46), 0 0 28px rgba(143, 224, 196,.14), 0 22px 54px rgba(0,0,0,.82); }
html[data-atmo="glasshouse"] h1, html[data-atmo="glasshouse"] h2 { background: linear-gradient(180deg, #ffffff, #c2f2e0 50%, #8fe0c4); -webkit-background-clip: text; background-clip: text; color: transparent; }
html[data-atmo="glasshouse"] h1 { filter: drop-shadow(0 2px 14px rgba(0,0,0,.9)) drop-shadow(0 0 2px rgba(0,0,0,.85)); }

